    std::cout << a + b << " " << a - b << " " << a * b << "\n";
    std::cout << a / b << " " << a % b << "\n";
    std::cout << std::boolalpha << (a == b) << " " << (a != b) << "\n";
    std::cout << (a != b && b != 0) << "\n";
}

